sp_widget.client_script:
api.controller = function($scope, spUtil) {
    var c = this;

    c.addNote = function() {
        if (!c.newNote) {
            alert("Please enter a note.");
            return;
        }

        c.server.update({
            action: 'addNote',
            taskSysId: c.data.task.sys_id,
            noteText: c.newNote
        }).then(function(response) {
            if (response.data.addNoteStatus === 'success') {
                alert("Work note added successfully.");
                spUtil.refresh($scope);  // Refresh widget
            } else {
                alert("Failed to add note.");
            }
        });
    };
};

sp_widget.css:
.hc-widget {
    border-radius: 8px;
    box-shadow: 0 2px 6px rgba(0,0,0,0.1);
    font-family: 'Poppins', sans-serif;
    margin-bottom: 20px;
}

.hc-widget .panel-heading {
    background-color: #7209b7; /* Deep Purple */
    color: #fff;
    padding: 12px 20px;
    border-radius: 8px 8px 0 0;
}

.hc-widget .panel-title a {
    color: #fff;
    text-decoration: none;
}

.list-group-item {
    border: none;
    border-bottom: 1px solid #eee;
}

sp_widget.script:
(function() {
    data.task = {};
    data.notes = [];

    var taskSysId = $sp.getParameter('sys_id');

    if (!taskSysId) {
        data.error = "No Task ID provided.";
        return;
    }

    // Fetch Task Details
    var taskGR = new GlideRecord('x_1790227_event_ma_event_task');
    if (taskGR.get(taskSysId)) {
        data.task = {
            sys_id: taskGR.getUniqueValue(),
            name: taskGR.getValue('u_task_name'),
            event: taskGR.getDisplayValue('u_event_id'),
            assigned_to: taskGR.getDisplayValue('u_assigned_to'),
            due_date: taskGR.getDisplayValue('u_due_date'),
            status: taskGR.getDisplayValue('u_status'),
            description: taskGR.getValue('u_description')
        };
    } else {
        data.error = "Task not found.";
        return;
    }

    // Fetch Work Notes
    var noteGR = new GlideRecord('sys_journal_field');
    noteGR.addQuery('element_id', taskSysId);
    noteGR.addQuery('element', 'work_notes');
    noteGR.query();

    while (noteGR.next()) {
        data.notes.push({
            sys_created_on: noteGR.getDisplayValue('sys_created_on'),
            sys_created_by: noteGR.getDisplayValue('sys_created_by'),
            value: noteGR.getValue('value')
        });
    }

    // Handle Add Work Note from Client
    if (input && input.action === 'addNote') {
        var task = new GlideRecord('x_1790227_event_ma_event_task');
        if (task.get(input.taskSysId)) {
            task.work_notes = input.noteText;
            task.update();
            data.addNoteStatus = 'success';
        } else {
            data.addNoteStatus = 'failure';
        }
    }
})();
